{
  "architecture": {
    "services": [
      {
        "name": "calc",
        "path": "services/calc",
        "language": "go",
        "public_interface": {
          "kind": "ui",
          "elements": [
            {
              "page": "Calc",
              "role": "button",
              "name": "Halve"
            },
            {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          ]
        }
      }
    ],
    "concepts": [
      {
        "concept": "number ready",
        "block": "given",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Parse the Given step’s numeral as a decimal number, replace the entire Number textbox value with its decimal representation, and leave it set before the action."
      },
      {
        "concept": "halve",
        "block": "when",
        "service": "calc",
        "intent": "Halve the number already present in the Calc page textbox named \"Number\" by pressing the Calc page button named \"Halve\" exactly once. Do not type, clear or re-enter the number, do not compute or write any value yourself, and do not press \"Halve\" a second time or interact with any other element; after the single press, leave the page as it is so the Then step can read the Number textbox."
      },
      {
        "concept": "number result",
        "block": "then",
        "service": "calc",
        "references": [
          {
            "element": {
              "page": "Calc",
              "role": "textbox",
              "name": "Number"
            }
          }
        ],
        "does": "Read the Number textbox value, parse it as a decimal number and assert numeric equality with the expected numeral supplied by the Then step."
      }
    ],
    "terms": []
  }
}
